INSERT INTO `ai_suggestion_logs` (`id`, `user_id`, `type`, `input_ingredients`, `output_response`, `saved_recipe_id`, `created_at`) VALUES (1,4,'ZERO_WASTE','[\"Thịt bò nạm — 500 g ⚠️ SẮP HẾT HẠN\", \"Bắp cải — 200 g ⚠️ SẮP HẾT HẠN\", \"Cải thìa — 200 g ⚠️ SẮP HẾT HẠN\", \"Muối — 200 g\", \"Nước mắm — 500 g\", \"Đường trắng — 500 g\", \"Bột ngọt — 200 g\"]','{\"steps\": [{\"stepNumber\": 1, \"instruction\": \"Sơ chế thịt bò: Rửa sạch thịt bò nạm, dùng khăn giấy thấm khô rồi thái lát mỏng ngang thớ để thịt không bị dai khi xào.\"}, {\"stepNumber\": 2, \"instruction\": \"Sơ chế rau: Bắp cải thái miếng vừa ăn (khoảng 3cm). Cải thìa tách lá, rửa sạch, nếu cây to có thể chẻ đôi theo chiều dọc.\"}, {\"stepNumber\": 3, \"instruction\": \"Ướp thịt: Trộn thịt bò với 10g nước mắm, 5g đường và 1g bột ngọt. Để thịt thấm gia vị trong khoảng 10 phút.\"}, {\"stepNumber\": 4, \"instruction\": \"Xào thịt bò: Làm nóng chảo với một ít dầu ăn, cho thịt bò vào xào ở lửa lớn thật nhanh tay. Khi thịt vừa chuyển màu tái thì trút ngay ra đĩa riêng.\"}, {\"stepNumber\": 5, \"instruction\": \"Xào rau: Sử dụng tiếp chảo đó, cho bắp cải vào xào trước khoảng 2 phút, sau đó cho cải thìa vào. Nêm thêm 10g nước mắm, 5g đường, 5g muối và phần bột ngọt còn lại.\"}, {\"stepNumber\": 6, \"instruction\": \"Hoàn thiện: Khi rau đã chín tới và giữ được độ giòn, cho thịt bò vào đảo đều lại trong 30 giây rồi tắt bếp. Trình bày ra đĩa và thưởng thức cùng cơm nóng.\"}], \"title\": \"Bò Nạm Xào Thập Cẩm Rau Xanh\", \"cookTime\": 15, \"prepTime\": 15, \"difficulty\": \"EASY\", \"description\": \"Một món xào đậm đà, kết hợp giữa vị béo nhẹ của nạm bò và độ giòn ngọt tự nhiên từ bắp cải cùng cải thìa, giúp tận dụng tối đa các nguyên liệu tươi ngon trong tủ lạnh.\", \"ingredients\": [{\"unit\": \"g\", \"amount\": 500, \"ingredientName\": \"Thịt bò nạm\"}, {\"unit\": \"g\", \"amount\": 200, \"ingredientName\": \"Bắp cải\"}, {\"unit\": \"g\", \"amount\": 200, \"ingredientName\": \"Cải thìa\"}, {\"unit\": \"g\", \"amount\": 20, \"ingredientName\": \"Nước mắm\"}, {\"unit\": \"g\", \"amount\": 10, \"ingredientName\": \"Đường trắng\"}, {\"unit\": \"g\", \"amount\": 5, \"ingredientName\": \"Muối\"}, {\"unit\": \"g\", \"amount\": 2, \"ingredientName\": \"Bột ngọt\"}], \"baseServings\": 4}',1,'2026-09-04 17:05:21'),(2,4,'FEASIBLE_FINDER','[\"Thịt bò\", \"Cà chua\", \"Nấm kim châm\"]','{\"steps\": [{\"stepNumber\": 1, \"instruction\": \"Sơ chế: Thịt bò thái lát mỏng, ướp với tỏi băm, một ít hạt nêm và tiêu trong 10 phút. Cà chua rửa sạch, bổ múi cau. Nấm kim châm cắt bỏ gốc, rửa sạch, tách nhỏ và để ráo nước.\"}, {\"stepNumber\": 2, \"instruction\": \"Xào thịt bò: Phi thơm một nửa phần hành tím với dầu ăn, cho thịt bò vào xào nhanh tay trên lửa lớn cho đến khi thịt vừa chín tái thì trút ra đĩa riêng.\"}, {\"stepNumber\": 3, \"instruction\": \"Nấu nước dùng: Cho phần hành tím còn lại vào nồi xào cùng cà chua cho đến khi cà chua chín mềm và ra màu đẹp. Thêm khoảng 600ml nước vào đun sôi.\"}, {\"stepNumber\": 4, \"instruction\": \"Hoàn thiện: Khi nước sôi, cho nấm kim châm vào nấu khoảng 1 phút. Sau đó cho phần thịt bò đã xào vào nồi, nêm nếm lại gia vị cho vừa ăn rồi tắt bếp ngay để thịt không bị dai.\"}, {\"stepNumber\": 5, \"instruction\": \"Trình bày: Múc canh ra bát, rắc thêm một chút tiêu xay lên trên và dùng nóng với cơm trắng.\"}], \"title\": \"Canh thịt bò nấu cà chua và nấm kim châm\", \"cookTime\": 15, \"prepTime\": 10, \"difficulty\": \"EASY\", \"description\": \"Món canh thanh mát, bổ dưỡng với vị chua nhẹ từ cà chua kết hợp cùng thịt bò mềm và nấm kim châm giòn ngọt. Đây là món ăn lý tưởng cho bữa cơm gia đình ấm cúng và dễ thực hiện.\", \"ingredients\": [{\"unit\": \"g\", \"amount\": 200, \"ingredientName\": \"Thịt bò\"}, {\"unit\": \"quả\", \"amount\": 2, \"ingredientName\": \"Cà chua\"}, {\"unit\": \"g\", \"amount\": 150, \"ingredientName\": \"Nấm kim châm\"}, {\"unit\": \"muỗng cà phê\", \"amount\": 1, \"ingredientName\": \"Tỏi băm\"}, {\"unit\": \"muỗng cà phê\", \"amount\": 1, \"ingredientName\": \"Hành tím băm\"}, {\"unit\": \"g\", \"amount\": 10, \"ingredientName\": \"Gia vị (muối, hạt nêm, tiêu, dầu ăn)\"}], \"baseServings\": 2}',4,'2026-09-04 17:11:15'),(3,4,'ZERO_WASTE','[\"Thịt bò nạm — 500 g ⚠️ SẮP HẾT HẠN\", \"Bắp cải — 200 g ⚠️ SẮP HẾT HẠN\", \"Cải thìa — 200 g ⚠️ SẮP HẾT HẠN\", \"Muối — 200 g\", \"Nước mắm — 500 g\", \"Đường trắng — 500 g\", \"Bột ngọt — 200 g\"]','{\"steps\": [{\"stepNumber\": 1, \"instruction\": \"Sơ chế thịt bò nạm: Rửa sạch, để ráo nước. Thái thịt thành các lát thật mỏng theo thớ ngang để thịt không bị dai khi xào.\"}, {\"stepNumber\": 2, \"instruction\": \"Ướp thịt bò với 1 muỗng canh nước mắm, 1/2 muỗng cà phê đường và một chút bột ngọt trong khoảng 10-15 phút cho thấm gia vị.\"}, {\"stepNumber\": 3, \"instruction\": \"Rửa sạch rau: Bắp cải thái miếng vừa ăn (khoảng 3cm); cải thìa tách bẹ, nếu bẹ to có thể chẻ đôi.\"}, {\"stepNumber\": 4, \"instruction\": \"Làm nóng chảo với một ít dầu ăn, cho thịt bò vào xào nhanh tay trên lửa lớn cho đến khi thịt vừa chín tái thì trút ra đĩa riêng.\"}, {\"stepNumber\": 5, \"instruction\": \"Sử dụng lại chảo đó, cho bắp cải vào xào trước khoảng 2 phút, sau đó cho cải thìa vào xào chung. Nêm một chút muối và nước mắm cho vừa khẩu vị.\"}, {\"stepNumber\": 6, \"instruction\": \"Khi rau vừa chín tới, cho đĩa thịt bò vào lại chảo, đảo nhanh tay trong 1 phút để các nguyên liệu hòa quyện rồi tắt bếp, trình bày ra đĩa.\"}], \"title\": \"Bò Nạm Xào Thập Cẩm Bắp Cải Và Cải Thìa\", \"cookTime\": 10, \"prepTime\": 15, \"nutrition\": {\"fat\": 102, \"carbs\": 18, \"protein\": 95, \"calories\": 1380}, \"difficulty\": \"EASY\", \"description\": \"Một món xào đậm đà, tận dụng độ ngọt tự nhiên từ bắp cải và cải thìa kết hợp với vị béo đặc trưng của nạm bò, giúp giải quyết nhanh các nguyên liệu sắp hết hạn mà vẫn đảm bảo dinh dưỡng.\", \"ingredients\": [{\"unit\": \"g\", \"amount\": 500, \"ingredientName\": \"Thịt bò nạm\"}, {\"unit\": \"g\", \"amount\": 200, \"ingredientName\": \"Bắp cải\"}, {\"unit\": \"g\", \"amount\": 200, \"ingredientName\": \"Cải thìa\"}, {\"unit\": \"ml\", \"amount\": 30, \"ingredientName\": \"Nước mắm\"}, {\"unit\": \"g\", \"amount\": 10, \"ingredientName\": \"Đường trắng\"}, {\"unit\": \"g\", \"amount\": 5, \"ingredientName\": \"Muối\"}, {\"unit\": \"g\", \"amount\": 5, \"ingredientName\": \"Bột ngọt\"}], \"baseServings\": 4}',2,'2026-09-05 08:13:43'),(4,4,'FEASIBLE_FINDER','[\"nấu\", \"cho\", \"tôi\", \"các\", \"món\", \"ăn\", \"với\", \"thịt\", \"heo\"]','{\"steps\": [{\"stepNumber\": 1, \"instruction\": \"Thịt heo rửa sạch với nước muối loãng, để ráo và thái miếng vừa ăn khoảng 2-3cm.\"}, {\"stepNumber\": 2, \"instruction\": \"Ướp thịt với hành tím băm, tỏi băm, 1 muỗng canh nước mắm, 1/2 muỗng đường và một ít tiêu trong khoảng 15 phút để thấm gia vị.\"}, {\"stepNumber\": 3, \"instruction\": \"Cho dầu ăn và phần đường còn lại vào nồi, đun lửa vừa cho đến khi đường chuyển sang màu cánh gián (nước màu).\"}, {\"stepNumber\": 4, \"instruction\": \"Cho thịt đã ướp vào nồi, đảo đều tay ở lửa lớn cho thịt săn lại và thấm màu.\"}, {\"stepNumber\": 5, \"instruction\": \"Thêm một chút nước lọc xấp mặt thịt, hạ lửa nhỏ và kho liu riu cho đến khi nước sốt sệt lại. Nêm nếm lại cho vừa miệng.\"}, {\"stepNumber\": 6, \"instruction\": \"Rắc thêm thật nhiều tiêu đen xay lên trên và tắt bếp. Trình bày ra đĩa dùng kèm với cơm trắng.\"}], \"title\": \"Thịt heo kho tiêu\", \"cookTime\": 20, \"prepTime\": 15, \"nutrition\": {\"fat\": 48, \"carbs\": 12, \"protein\": 45, \"calories\": 650}, \"difficulty\": \"EASY\", \"description\": \"Một món ăn gia đình truyền thống của Việt Nam với thịt heo mềm thấm vị mặn ngọt, cay nồng của tiêu đen. Món ăn này rất giàu protein và cực kỳ phù hợp khi ăn kèm với cơm nóng.\", \"ingredients\": [{\"unit\": \"g\", \"amount\": 300, \"ingredientName\": \"Thịt heo (ba chỉ hoặc nạc vai)\"}, {\"unit\": \"củ\", \"amount\": 2, \"ingredientName\": \"Hành tím\"}, {\"unit\": \"tép\", \"amount\": 3, \"ingredientName\": \"Tỏi\"}, {\"unit\": \"muỗng canh\", \"amount\": 2, \"ingredientName\": \"Nước mắm\"}, {\"unit\": \"muỗng canh\", \"amount\": 1, \"ingredientName\": \"Đường\"}, {\"unit\": \"muỗng cà phê\", \"amount\": 1, \"ingredientName\": \"Tiêu đen xay\"}, {\"unit\": \"muỗng canh\", \"amount\": 1, \"ingredientName\": \"Dầu ăn\"}], \"baseServings\": 2}',5,'2026-09-05 15:02:25'),(5,4,'ZERO_WASTE','[\"Thịt bò nạm — 500 g ⚠️ SẮP HẾT HẠN\", \"Bắp cải — 200 g ⚠️ SẮP HẾT HẠN\", \"Cải thìa — 200 g ⚠️ SẮP HẾT HẠN\", \"Muối — 200 g\", \"Nước mắm — 500 ml\", \"Đường trắng — 500 g\", \"Bột ngọt — 200 g\"]','{\"steps\": [{\"stepNumber\": 1, \"instruction\": \"Sơ chế thịt bò: Rửa sạch nạm bò, dùng khăn thấm khô. Thái thịt thành lát mỏng ngang thớ để khi xào thịt không bị dai.\"}, {\"stepNumber\": 2, \"instruction\": \"Ướp thịt: Cho thịt vào tô, ướp với 1 muỗng canh nước mắm, 1 muỗng cà phê đường và một chút bột ngọt. Để thịt thấm trong 15 phút.\"}, {\"stepNumber\": 3, \"instruction\": \"Sơ chế rau: Bắp cải rửa sạch, thái sợi bản vừa (khoảng 1cm). Cải thìa tách bẹ, rửa sạch, bẹ lớn có thể chẻ đôi.\"}, {\"stepNumber\": 4, \"instruction\": \"Xào thịt bò: Làm nóng chảo với một ít dầu ăn (nếu có), cho thịt bò vào xào nhanh tay trên lửa lớn đến khi thịt vừa chuyển màu (chín tái) thì trút ra đĩa riêng.\"}, {\"stepNumber\": 5, \"instruction\": \"Xào rau: Vẫn dùng chảo đó, cho bắp cải và cải thìa vào xào. Thêm 1 muỗng canh nước mắm và 1 muỗng cà phê đường. Nếu chảo quá khô có thể cho thêm một chút nước lọc.\"}, {\"stepNumber\": 6, \"instruction\": \"Hoàn thiện: Khi rau đã chín tới và vẫn giữ được độ giòn, cho thịt bò vào lại chảo, đảo đều trong khoảng 1 phút để các nguyên liệu hòa quyện rồi tắt bếp. Trình bày ra đĩa và dùng nóng với cơm.\"}], \"title\": \"Bò Nạm Xào Thập Cẩm\", \"cookTime\": 15, \"prepTime\": 15, \"nutrition\": {\"fat\": 105, \"carbs\": 18, \"protein\": 94, \"calories\": 1335}, \"difficulty\": \"EASY\", \"description\": \"Một món xào đậm đà, tận dụng vị ngọt thanh của bắp cải và cải thìa để làm nổi bật hương vị béo ngậy của nạm bò. Đây là món ăn giàu đạm và chất xơ, rất phù hợp cho bữa cơm gia đình.\", \"ingredients\": [{\"fat\": 19, \"unit\": \"g\", \"carbs\": 0, \"amount\": 500, \"protein\": 18, \"ingredientName\": \"Thịt bò nạm\", \"caloriesPer100g\": 250}, {\"fat\": 0, \"unit\": \"g\", \"carbs\": 6, \"amount\": 200, \"protein\": 1, \"ingredientName\": \"Bắp cải\", \"caloriesPer100g\": 25}, {\"fat\": 0, \"unit\": \"g\", \"carbs\": 2, \"amount\": 200, \"protein\": 2, \"ingredientName\": \"Cải thìa\", \"caloriesPer100g\": 13}, {\"fat\": 0, \"unit\": \"ml\", \"carbs\": 4, \"amount\": 30, \"protein\": 5, \"ingredientName\": \"Nước mắm\", \"caloriesPer100g\": 35}, {\"fat\": 0, \"unit\": \"g\", \"carbs\": 100, \"amount\": 15, \"protein\": 0, \"ingredientName\": \"Đường trắng\", \"caloriesPer100g\": 387}], \"baseServings\": 3}',6,'2026-09-09 09:35:39'),(6,4,'FEASIBLE_FINDER','[\"Nấu\", \"cho\", \"tôi\", \"món\", \"ăn\", \"từ\", \"thịt\", \"heo\", \"và\", \"cà\", \"chua\"]','{\"steps\": [{\"stepNumber\": 1, \"instruction\": \"Sơ chế: Thịt heo rửa sạch với nước muối loãng, thái miếng mỏng vừa ăn. Cà chua rửa sạch, thái múi cau hoặc băm nhỏ để khi nấu nhanh tạo thành sốt.\"}, {\"stepNumber\": 2, \"instruction\": \"Ướp thịt: Cho thịt vào bát, ướp với 1 thìa cà phê nước mắm, một ít tiêu và một nửa phần hành tím băm nhỏ trong khoảng 10 phút.\"}, {\"stepNumber\": 3, \"instruction\": \"Xào thịt: Làm nóng chảo với một ít dầu ăn, phi thơm phần hành tím còn lại. Cho thịt heo vào xào ở lửa lớn cho đến khi thịt săn lại và hơi cháy cạnh, sau đó trút thịt ra đĩa riêng.\"}, {\"stepNumber\": 4, \"instruction\": \"Làm sốt cà chua: Dùng chính chảo đó, thêm một chút dầu nếu cần, cho cà chua vào xào. Thêm một chút nước lọc và đậy vung lại khoảng 2-3 phút cho cà chua chín nhừ.\"}, {\"stepNumber\": 5, \"instruction\": \"Hoàn thiện: Đổ phần thịt đã xào vào chảo sốt cà chua, đảo đều. Nêm thêm đường và nước mắm cho vừa khẩu vị chua ngọt. Đun thêm 2 phút cho thịt ngấm sốt rồi tắt bếp, trình bày ra đĩa.\"}], \"title\": \"Thịt heo sốt cà chua đậm đà\", \"cookTime\": 15, \"prepTime\": 10, \"nutrition\": {\"fat\": 55, \"carbs\": 15, \"protein\": 83, \"calories\": 890}, \"difficulty\": \"EASY\", \"description\": \"Một món ăn gia đình kinh điển với vị chua nhẹ từ cà chua chín mọng hòa quyện cùng vị ngọt thanh của thịt heo. Món này rất giàu protein và Lycopene, cực kỳ bắt cơm trong các bữa tối gia đình.\", \"ingredients\": [{\"fat\": 14, \"unit\": \"g\", \"carbs\": 0, \"amount\": 300, \"protein\": 27, \"ingredientName\": \"Thịt heo (nạc vai hoặc ba chỉ)\", \"caloriesPer100g\": 242}, {\"fat\": 0, \"unit\": \"g\", \"carbs\": 4, \"amount\": 200, \"protein\": 1, \"ingredientName\": \"Cà chua chín\", \"caloriesPer100g\": 18}, {\"fat\": 0, \"unit\": \"g\", \"carbs\": 17, \"amount\": 20, \"protein\": 2, \"ingredientName\": \"Hành tím\", \"caloriesPer100g\": 72}, {\"fat\": 100, \"unit\": \"ml\", \"carbs\": 0, \"amount\": 15, \"protein\": 0, \"ingredientName\": \"Dầu ăn\", \"caloriesPer100g\": 884}], \"baseServings\": 2}',NULL,'2026-09-09 09:37:58'),(7,4,'ZERO_WASTE','[\"Thịt bò thăn nội — 400 g ⚠️ SẮP HẾT HẠN\", \"Thịt bò nạm — 400 g ⚠️ SẮP HẾT HẠN\", \"Hành tây — 200 g\", \"Hành lá — 200 g\", \"Cá hồi — 300 g\", \"Chuối — 400 g\", \"Bạch tuộc — 250 g\", \"Cam — 500 g\", \"Sữa tươi nguyên kem — 1000 ml\", \"Trứng gà — 500 g\", \"Bún gạo khô — 500 g\", \"Hạt điều — 200 g\", \"Hạnh nhân — 200 g\", \"Dầu bơ — 250 g\", \"Bột ngọt — 200 g\", \"Đường trắng — 500 g\", \"Muối — 200 g\", \"Nước mắm — 500 ml\", \"Bột mì đa dụng — 1000 g\", \"Dầu đậu nành — 500 g\", \"Hạt nêm — 20 g\"]','{\"steps\": [{\"stepNumber\": 1, \"instruction\": \"Thịt bò thăn nội và nạm rửa sạch, thấm khô. Thái mỏng cả hai loại thịt (lưu ý thái nạm bò thật mỏng ngang thớ để không bị dai).\"}, {\"stepNumber\": 2, \"instruction\": \"Ướp thịt bò với 1 thìa canh nước mắm, 1 thìa cà phê đường, 1 thìa cà phê hạt nêm và một ít dầu ăn trong 15 phút.\"}, {\"stepNumber\": 3, \"instruction\": \"Bún gạo khô ngâm nước ấm cho mềm rồi luộc sơ qua nước sôi khoảng 2-3 phút, vớt ra xả nước lạnh và để ráo nước.\"}, {\"stepNumber\": 4, \"instruction\": \"Hành tây bóc vỏ thái múi cau. Hành lá rửa sạch, cắt khúc 3cm.\"}, {\"stepNumber\": 5, \"instruction\": \"Làm nóng chảo với dầu đậu nành, cho thịt bò vào xào ở lửa lớn thật nhanh tay cho đến khi thịt vừa chín tái thì trút riêng ra đĩa.\"}, {\"stepNumber\": 6, \"instruction\": \"Vẫn dùng chảo đó, thêm ít dầu rồi cho hành tây vào xào thơm. Tiếp theo cho bún gạo vào đảo đều, nêm thêm chút nước mắm và đường cho vừa vị.\"}, {\"stepNumber\": 7, \"instruction\": \"Cuối cùng, cho thịt bò đã xào và hành lá vào chảo bún, đảo nhanh tay trong 1 phút để các nguyên liệu hòa quyện rồi tắt bếp. Trình bày ra đĩa và thưởng thức nóng.\"}], \"title\": \"Bún Bò Xào Hành Tây\", \"cookTime\": 15, \"prepTime\": 20, \"nutrition\": {\"fat\": 170, \"carbs\": 420, \"protein\": 215, \"calories\": 4250}, \"difficulty\": \"MEDIUM\", \"description\": \"Một món ăn đậm đà, kết hợp giữa độ mềm của thăn nội và độ giòn dai của nạm bò, quyện cùng hương vị thơm nồng của hành tây và bún gạo dai ngon.\", \"ingredients\": [{\"fat\": 15, \"unit\": \"g\", \"carbs\": 0, \"amount\": 400, \"protein\": 26, \"ingredientName\": \"Thịt bò thăn nội\", \"caloriesPer100g\": 250}, {\"fat\": 19, \"unit\": \"g\", \"carbs\": 0, \"amount\": 400, \"protein\": 18, \"ingredientName\": \"Thịt bò nạm\", \"caloriesPer100g\": 250}, {\"fat\": 0, \"unit\": \"g\", \"carbs\": 80, \"amount\": 500, \"protein\": 7, \"ingredientName\": \"Bún gạo khô\", \"caloriesPer100g\": 360}, {\"fat\": 0, \"unit\": \"g\", \"carbs\": 9, \"amount\": 200, \"protein\": 1, \"ingredientName\": \"Hành tây\", \"caloriesPer100g\": 40}, {\"fat\": 0, \"unit\": \"g\", \"carbs\": 7, \"amount\": 100, \"protein\": 2, \"ingredientName\": \"Hành lá\", \"caloriesPer100g\": 32}, {\"fat\": 100, \"unit\": \"g\", \"carbs\": 0, \"amount\": 40, \"protein\": 0, \"ingredientName\": \"Dầu đậu nành\", \"caloriesPer100g\": 884}, {\"fat\": 0, \"unit\": \"g\", \"carbs\": 100, \"amount\": 20, \"protein\": 0, \"ingredientName\": \"Đường trắng\", \"caloriesPer100g\": 387}, {\"fat\": 0, \"unit\": \"ml\", \"carbs\": 5, \"amount\": 50, \"protein\": 10, \"ingredientName\": \"Nước mắm\", \"caloriesPer100g\": 60}], \"baseServings\": 4}',7,'2026-09-17 08:35:59');
