INSERT INTO `recipe_steps` (`id`, `recipe_id`, `step_number`, `title`, `instruction`, `image_url`) VALUES (1,1,1,NULL,'Sơ chế thịt bò: Rửa sạch thịt bò nạm, dùng khăn giấy thấm khô rồi thái lát mỏng ngang thớ để thịt không bị dai khi xào.',NULL),(2,1,2,NULL,'Sơ chế rau: Bắp cải thái miếng vừa ăn (khoảng 3cm). Cải thìa tách lá, rửa sạch, nếu cây to có thể chẻ đôi theo chiều dọc.',NULL),(3,1,3,NULL,'Ướp thịt: Trộn thịt bò với 10g nước mắm, 5g đường và 1g bột ngọt. Để thịt thấm gia vị trong khoảng 10 phút.',NULL),(4,1,4,NULL,'Xào thịt bò: Làm nóng chảo với một ít dầu ăn, cho thịt bò vào xào ở lửa lớn thật nhanh tay. Khi thịt vừa chuyển màu tái thì trút ngay ra đĩa riêng.',NULL),(5,1,5,NULL,'Xào rau: Sử dụng tiếp chảo đó, cho bắp cải vào xào trước khoảng 2 phút, sau đó cho cải thìa vào. Nêm thêm 10g nước mắm, 5g đường, 5g muối và phần bột ngọt còn lại.',NULL),(6,1,6,NULL,'Hoàn thiện: Khi rau đã chín tới và giữ được độ giòn, cho thịt bò vào đảo đều lại trong 30 giây rồi tắt bếp. Trình bày ra đĩa và thưởng thức cùng cơm nóng.',NULL),(7,2,1,NULL,'Sơ chế thịt bò nạm: Rửa sạch, để ráo nước. Thái thịt thành các lát thật mỏng theo thớ ngang để thịt không bị dai khi xào.',NULL),(8,2,2,NULL,'Ướp thịt bò với 1 muỗng canh nước mắm, 1/2 muỗng cà phê đường và một chút bột ngọt trong khoảng 10-15 phút cho thấm gia vị.',NULL),(9,2,3,NULL,'Rửa sạch rau: Bắp cải thái miếng vừa ăn (khoảng 3cm); cải thìa tách bẹ, nếu bẹ to có thể chẻ đôi.',NULL),(10,2,4,NULL,'Làm nóng chảo với một ít dầu ăn, cho thịt bò vào xào nhanh tay trên lửa lớn cho đến khi thịt vừa chín tái thì trút ra đĩa riêng.',NULL),(11,2,5,NULL,'Sử dụng lại chảo đó, cho bắp cải vào xào trước khoảng 2 phút, sau đó cho cải thìa vào xào chung. Nêm một chút muối và nước mắm cho vừa khẩu vị.',NULL),(12,2,6,NULL,'Khi rau vừa chín tới, cho đĩa thịt bò vào lại chảo, đảo nhanh tay trong 1 phút để các nguyên liệu hòa quyện rồi tắt bếp, trình bày ra đĩa.',NULL),(13,3,1,'Bước 1','Sơ chế nguyên liệu','https://res.cloudinary.com/nipfq9hg/image/upload/v1788596695/smartrecipe/recipes/steps/4fa51d59-2907-43fe-af8a-1d3b21f7c0ad.jpg'),(14,3,2,'Bước 2','Xào hành','https://res.cloudinary.com/nipfq9hg/image/upload/v1788596697/smartrecipe/recipes/steps/dde21b3c-9a0a-4a26-8c5e-bedd36d1f6cc.jpg'),(15,3,3,'Bước 3','Đun xôi nước','https://res.cloudinary.com/nipfq9hg/image/upload/v1788596699/smartrecipe/recipes/steps/96a75ca7-1bff-48f1-b450-945a681e953a.jpg'),(16,3,4,'Bước 4','Cho thịt bò vào','https://res.cloudinary.com/nipfq9hg/image/upload/v1788596701/smartrecipe/recipes/steps/66dd15fd-cd20-4b87-a2dc-af89d64998b1.jpg'),(17,3,5,'Bước 5','Hoàn thiện','https://res.cloudinary.com/nipfq9hg/image/upload/v1788596703/smartrecipe/recipes/steps/c0e80ac1-11e1-4289-8481-a008b1b1fabd.jpg'),(18,4,1,NULL,'Sơ chế: Thịt bò thái lát mỏng, ướp với tỏi băm, một ít hạt nêm và tiêu trong 10 phút. Cà chua rửa sạch, bổ múi cau. Nấm kim châm cắt bỏ gốc, rửa sạch, tách nhỏ và để ráo nước.',NULL),(19,4,2,NULL,'Xào thịt bò: Phi thơm một nửa phần hành tím với dầu ăn, cho thịt bò vào xào nhanh tay trên lửa lớn cho đến khi thịt vừa chín tái thì trút ra đĩa riêng.',NULL),(20,4,3,NULL,'Nấu nước dùng: Cho phần hành tím còn lại vào nồi xào cùng cà chua cho đến khi cà chua chín mềm và ra màu đẹp. Thêm khoảng 600ml nước vào đun sôi.',NULL),(21,4,4,NULL,'Hoàn thiện: Khi nước sôi, cho nấm kim châm vào nấu khoảng 1 phút. Sau đó cho phần thịt bò đã xào vào nồi, nêm nếm lại gia vị cho vừa ăn rồi tắt bếp ngay để thịt không bị dai.',NULL),(22,4,5,NULL,'Trình bày: Múc canh ra bát, rắc thêm một chút tiêu xay lên trên và dùng nóng với cơm trắng.',NULL),(23,5,1,NULL,'Thịt heo rửa sạch với nước muối loãng, để ráo và thái miếng vừa ăn khoảng 2-3cm.',NULL),(24,5,2,NULL,'Ướp thịt với hành tím băm, tỏi băm, 1 muỗng canh nước mắm, 1/2 muỗng đường và một ít tiêu trong khoảng 15 phút để thấm gia vị.',NULL),(25,5,3,NULL,'Cho dầu ăn và phần đường còn lại vào nồi, đun lửa vừa cho đến khi đường chuyển sang màu cánh gián (nước màu).',NULL),(26,5,4,NULL,'Cho thịt đã ướp vào nồi, đảo đều tay ở lửa lớn cho thịt săn lại và thấm màu.',NULL),(27,5,5,NULL,'Thêm một chút nước lọc xấp mặt thịt, hạ lửa nhỏ và kho liu riu cho đến khi nước sốt sệt lại. Nêm nếm lại cho vừa miệng.',NULL),(28,5,6,NULL,'Rắc thêm thật nhiều tiêu đen xay lên trên và tắt bếp. Trình bày ra đĩa dùng kèm với cơm trắng.',NULL),(29,6,1,NULL,'Sơ chế thịt bò: Rửa sạch nạm bò, dùng khăn thấm khô. Thái thịt thành lát mỏng ngang thớ để khi xào thịt không bị dai.',NULL),(30,6,2,NULL,'Ướp thịt: Cho thịt vào tô, ướp với 1 muỗng canh nước mắm, 1 muỗng cà phê đường và một chút bột ngọt. Để thịt thấm trong 15 phút.',NULL),(31,6,3,NULL,'Sơ chế rau: Bắp cải rửa sạch, thái sợi bản vừa (khoảng 1cm). Cải thìa tách bẹ, rửa sạch, bẹ lớn có thể chẻ đôi.',NULL),(32,6,4,NULL,'Xào thịt bò: Làm nóng chảo với một ít dầu ăn (nếu có), cho thịt bò vào xào nhanh tay trên lửa lớn đến khi thịt vừa chuyển màu (chín tái) thì trút ra đĩa riêng.',NULL),(33,6,5,NULL,'Xào rau: Vẫn dùng chảo đó, cho bắp cải và cải thìa vào xào. Thêm 1 muỗng canh nước mắm và 1 muỗng cà phê đường. Nếu chảo quá khô có thể cho thêm một chút nước lọc.',NULL),(34,6,6,NULL,'Hoàn thiện: Khi rau đã chín tới và vẫn giữ được độ giòn, cho thịt bò vào lại chảo, đảo đều trong khoảng 1 phút để các nguyên liệu hòa quyện rồi tắt bếp. Trình bày ra đĩa và dùng nóng với cơm.',NULL),(35,7,1,NULL,'Thịt bò thăn nội và nạm rửa sạch, thấm khô. Thái mỏng cả hai loại thịt (lưu ý thái nạm bò thật mỏng ngang thớ để không bị dai).',NULL),(36,7,2,NULL,'Ướp thịt bò với 1 thìa canh nước mắm, 1 thìa cà phê đường, 1 thìa cà phê hạt nêm và một ít dầu ăn trong 15 phút.',NULL),(37,7,3,NULL,'Bún gạo khô ngâm nước ấm cho mềm rồi luộc sơ qua nước sôi khoảng 2-3 phút, vớt ra xả nước lạnh và để ráo nước.',NULL),(38,7,4,NULL,'Hành tây bóc vỏ thái múi cau. Hành lá rửa sạch, cắt khúc 3cm.',NULL),(39,7,5,NULL,'Làm nóng chảo với dầu đậu nành, cho thịt bò vào xào ở lửa lớn thật nhanh tay cho đến khi thịt vừa chín tái thì trút riêng ra đĩa.',NULL),(40,7,6,NULL,'Vẫn dùng chảo đó, thêm ít dầu rồi cho hành tây vào xào thơm. Tiếp theo cho bún gạo vào đảo đều, nêm thêm chút nước mắm và đường cho vừa vị.',NULL),(41,7,7,NULL,'Cuối cùng, cho thịt bò đã xào và hành lá vào chảo bún, đảo nhanh tay trong 1 phút để các nguyên liệu hòa quyện rồi tắt bếp. Trình bày ra đĩa và thưởng thức nóng.',NULL),(48,9,1,NULL,'Sơ chế thịt bò: Rửa sạch nạm bò, dùng khăn thấm khô. Thái thịt thành lát mỏng ngang thớ để khi xào thịt không bị dai.',NULL),(49,9,2,NULL,'Ướp thịt: Cho thịt vào tô, ướp với 1 muỗng canh nước mắm, 1 muỗng cà phê đường và một chút bột ngọt. Để thịt thấm trong 15 phút.',NULL),(50,9,3,NULL,'Sơ chế rau: Bắp cải rửa sạch, thái sợi bản vừa (khoảng 1cm). Cải thìa tách bẹ, rửa sạch, bẹ lớn có thể chẻ đôi.',NULL),(51,9,4,NULL,'Xào thịt bò: Làm nóng chảo với một ít dầu ăn (nếu có), cho thịt bò vào xào nhanh tay trên lửa lớn đến khi thịt vừa chuyển màu (chín tái) thì trút ra đĩa riêng.',NULL),(52,9,5,NULL,'Xào rau: Vẫn dùng chảo đó, cho bắp cải và cải thìa vào xào. Thêm 1 muỗng canh nước mắm và 1 muỗng cà phê đường. Nếu chảo quá khô có thể cho thêm một chút nước lọc.',NULL),(53,9,6,NULL,'Hoàn thiện: Khi rau đã chín tới và vẫn giữ được độ giòn, cho thịt bò vào lại chảo, đảo đều trong khoảng 1 phút để các nguyên liệu hòa quyện rồi tắt bếp. Trình bày ra đĩa và dùng nóng với cơm.',NULL),(54,10,1,NULL,'Sơ chế thịt bò: Rửa sạch nạm bò, dùng khăn thấm khô. Thái thịt thành lát mỏng ngang thớ để khi xào thịt không bị dai.',NULL),(55,10,2,NULL,'Ướp thịt: Cho thịt vào tô, ướp với 1 muỗng canh nước mắm, 1 muỗng cà phê đường và một chút bột ngọt. Để thịt thấm trong 15 phút.',NULL),(56,10,3,NULL,'Sơ chế rau: Bắp cải rửa sạch, thái sợi bản vừa (khoảng 1cm). Cải thìa tách bẹ, rửa sạch, bẹ lớn có thể chẻ đôi.',NULL),(57,10,4,NULL,'Xào thịt bò: Làm nóng chảo với một ít dầu ăn (nếu có), cho thịt bò vào xào nhanh tay trên lửa lớn đến khi thịt vừa chuyển màu (chín tái) thì trút ra đĩa riêng.',NULL),(58,10,5,NULL,'Xào rau: Vẫn dùng chảo đó, cho bắp cải và cải thìa vào xào. Thêm 1 muỗng canh nước mắm và 1 muỗng cà phê đường. Nếu chảo quá khô có thể cho thêm một chút nước lọc.',NULL),(59,10,6,NULL,'Hoàn thiện: Khi rau đã chín tới và vẫn giữ được độ giòn, cho thịt bò vào lại chảo, đảo đều trong khoảng 1 phút để các nguyên liệu hòa quyện rồi tắt bếp. Trình bày ra đĩa và dùng nóng với cơm.',NULL);
INSERT INTO `recipe_tags` (`id`, `recipe_id`, `tag_id`) VALUES (6,1,3),(7,2,2),(1,3,6),(4,4,5),(5,5,4);
INSERT INTO `recipes` (`id`, `author_id`, `cloned_from_id`, `title`, `base_servings`, `status`, `description`, `image_url`, `prep_time`, `cook_time`, `difficulty`, `like_count`, `created_at`, `updated_at`) VALUES (1,4,NULL,'Bò Nấm Xào Thập Cẩm Rau Xanh',4,'PUBLIC','Món xào nhanh gọn, thanh đạm và giàu dinh dưỡng kết hợp thịt bò mềm và nấm tươi giòn ngọt.','https://images.unsplash.com/photo-1512058564366-18510be2db19?w=1000&auto=format&fit=crop&q=80',15,15,'EASY',0,'2026-09-04 17:09:41','2026-09-10 14:17:50'),(2,4,NULL,'Bò Nấm Xào Thập Cẩm Bắp Cải Và Cải Thìa',4,'PUBLIC','Sự kết hợp tươi ngon giữa thịt bò, bắp cải giòn ngọt và cải thìa giàu chất xơ, thanh đạm cho bữa ăn.','https://images.unsplash.com/photo-1540420773420-3366772f4999?w=1000&auto=format&fit=crop&q=80',15,10,'EASY',0,'2026-09-05 08:13:58','2026-09-10 14:17:50'),(3,4,NULL,'Phở bò truyền thống',1,'PUBLIC','Món ăn đơn giản và dân giã','https://res.cloudinary.com/nipfq9hg/image/upload/v1788596693/smartrecipe/recipes/5440b548-2a54-4353-9245-80a1a35e2ae3.jpg',15,15,'EASY',1,'2026-09-05 08:24:02','2026-09-17 11:07:16'),(4,4,NULL,'Canh thịt bò nấu cà chua và nấm kim châm',2,'PUBLIC','Món canh thanh mát, bổ dưỡng kết hợp vị ngọt tự nhiên của thịt bò và chua thanh của cà chua.','https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1000&auto=format&fit=crop&q=80',15,20,'EASY',0,'2026-09-05 15:01:32','2026-09-10 14:17:50'),(5,4,NULL,'Thịt heo kho tiêu',2,'PUBLIC','Thịt heo kho tiêu đậm đà, thơm lừng hương tiêu cay nồng rất thích hợp cho bữa cơm gia đình.','https://images.unsplash.com/photo-1544025162-d76694265947?w=1000&auto=format&fit=crop&q=80',10,25,'MEDIUM',0,'2026-09-05 15:03:26','2026-09-10 14:17:50'),(6,4,NULL,'Bò Nạm Xào Thập Cẩm',3,'PUBLIC','Một món xào đậm đà, tận dụng vị ngọt thanh của bắp cải và cải thìa để làm nổi bật hương vị béo ngậy của nạm bò. Đây là món ăn giàu đạm và chất xơ, rất phù hợp cho bữa cơm gia đình.','https://res.cloudinary.com/nipfq9hg/image/upload/v1789490496/smartrecipe/recipes/swpwadsdqodkafiz4ysw.jpg',15,15,'EASY',0,'2026-09-09 09:36:19','2026-09-17 12:50:49'),(7,4,NULL,'Bún Bò Xào Hành Tây',4,'DRAFT','Một món ăn đậm đà, kết hợp giữa độ mềm của thăn nội và độ giòn dai của nạm bò, quyện cùng hương vị thơm nồng của hành tây và bún gạo dai ngon.',NULL,20,15,'MEDIUM',0,'2026-09-17 08:38:57','2026-09-17 11:07:16'),(9,3,6,'Bò Nạm Xào Thập Cẩm (Bản sao)',3,'PRIVATE','Một món xào đậm đà, tận dụng vị ngọt thanh của bắp cải và cải thìa để làm nổi bật hương vị béo ngậy của nạm bò. Đây là món ăn giàu đạm và chất xơ, rất phù hợp cho bữa cơm gia đình.','https://res.cloudinary.com/nipfq9hg/image/upload/v1789490496/smartrecipe/recipes/swpwadsdqodkafiz4ysw.jpg',15,15,'EASY',0,'2026-09-17 13:04:56','2026-09-17 13:04:56'),(10,4,9,'Bò Nạm Xào Thập Cẩm (Bản sao) (Bản sao)',3,'PRIVATE','Một món xào đậm đà, tận dụng vị ngọt thanh của bắp cải và cải thìa để làm nổi bật hương vị béo ngậy của nạm bò. Đây là món ăn giàu đạm và chất xơ, rất phù hợp cho bữa cơm gia đình.','https://res.cloudinary.com/nipfq9hg/image/upload/v1789490496/smartrecipe/recipes/swpwadsdqodkafiz4ysw.jpg',15,15,'EASY',0,'2026-09-17 15:32:30','2026-09-17 15:32:30');
